using System;
using System.IO;
using System.Media;
using System.Threading.Tasks;

namespace FortniteVideoSoftware.App;

public static class UiSoundEffect
{
    private static readonly byte[] SuccessWav = Convert.FromBase64String("");
    private static readonly byte[] CloseWav = Convert.FromBase64String("");
    private static readonly byte[] OpenWav = Convert.FromBase64String("");
    private static readonly byte[] GeneralWav = Convert.FromBase64String("");
    private static readonly byte[] ErrorWav = Convert.FromBase64String("");
    private static readonly byte[] MarkWav = Convert.FromBase64String("");

    public static void PlayProcess() => PlayBuffer(SuccessWav);
    public static void PlayClose() => PlayBuffer(CloseWav);
    public static void PlayOpen() => PlayBuffer(OpenWav);
    public static void PlayClick() => PlayBuffer(GeneralWav);
    public static void PlayError() => PlayBuffer(ErrorWav);
    public static void PlayMark() => PlayBuffer(MarkWav);

    private static void PlayBuffer(byte[] buffer)
    {
        if (buffer == null || buffer.Length < 100) return;
        Task.Run(() => 
        {
            try
            {
                using (var ms = new MemoryStream(buffer))
                using (var player = new SoundPlayer(ms))
                {
                    player.PlaySync();
                }
            }
            catch { }
        });
    }
}
